// src/components/Navbar.js
import React from "react";
import { Link } from "react-router-dom";

const Navbar = () => {
  return (
    <nav className="bg-black bg-opacity-80 text-blue-200 p-4 flex justify-between items-center shadow-lg">
      <div className="text-2xl font-bold">🎮 Gamify</div>
      <div className="space-x-4">
        <Link to="/" className="hover:text-white">Home</Link>
        <Link to="/register" className="hover:text-white">Register</Link>
        <Link to="/login" className="hover:text-white">Login</Link>
        <Link to="/courses" className="hover:text-white">Courses</Link>
        <Link to="/leaderboard" className="hover:text-white">Leaderboard</Link>
      </div>
    </nav>
  );
};

export default Navbar;
